SPECS=(
Spec(KnowledgeLesson(145,'Lesson_145-backup-pitr-and-what-a-backup-is-not','Backup, PITR and what a backup is not','33-backup-pitr-and-what-a-backup-is-not.md','wiki.database.backup-pitr-boundaries','Backup logical, backup vật lý và continuous archiving đáp ứng RPO/RTO nào, và điều kiện nào khiến một file sao lưu chưa đủ để gọi là khả năng khôi phục?',PG+('src.book.kleppmann-ddia.1e',),PGL+('SRC-KLEPPMANN-DDIA-1E',),(
('Backup là một chuỗi kiểm soát','Backup không phải file đơn lẻ mà là chuỗi capture, truyền, lưu, kiểm toàn vẹn, giữ phiên bản, khôi phục và đối soát. RPO quy định điểm dữ liệu cũ nhất chấp nhận được sau sự cố; RTO quy định thời gian đưa dịch vụ về trạng thái đủ dùng. Cả hai là quyết định nghiệp vụ theo từng dataset/service tier. Tần suất backup không tự bằng RPO nếu WAL/archive, upload hoặc catalog có khoảng trống.'),
('Logical backup','pg_dump tạo biểu diễn logic có thể nạp lại, thường thuận lợi khi chuyển phiên bản/kiến trúc và khôi phục chọn lọc. Nó không chứa mọi cluster-global object nếu chỉ dump một database; role và tablespace cần pg_dumpall globals hoặc quản lý riêng. Restore cần users, extensions, collation/locale, permissions và statistics. Dump nhất quán theo snapshot nhưng nhiều database dump riêng không có chung snapshot.'),
('Physical backup','Physical backup giữ data files/WAL ở mức cluster, nhanh hơn cho database lớn và cần tính tương thích version/platform nghiêm ngặt. Copy data directory tùy tiện khi server đang chạy không tạo consistent backup; cần shutdown hoặc snapshot/base-backup protocol đúng. Một table file riêng không đủ vì transaction status và catalog/WAL liên kết toàn cluster.'),
('PITR','Point-in-time recovery kết hợp base backup với chuỗi WAL liên tục rồi replay đến time, transaction ID, named restore point hoặc LSN mục tiêu. Recovery target phải dừng trước destructive transaction nhưng timestamp từ incident report có thể lệch clock/timezone. Phải giữ WAL từ lúc base backup bắt đầu đến target; một missing segment phá chuỗi. Timeline history quan trọng sau promotion/recovery.'),
('Những gì nằm ngoài data pages','Kế hoạch phải quản lý cấu hình, secrets/keys, roles, certificates, extensions/binaries, tablespaces, scheduler jobs, DNS/service discovery, monitoring và runbook/owners. Không nên nhét plaintext secret vào cùng backup nếu policy cấm; cần backup metadata/reference và quy trình cấp lại. Encryption key mất làm backup đúng checksum nhưng không đọc được.'),
('Retention và bất biến','Retention gồm full/base backups, WAL, catalog và keys, theo legal/deletion requirements. 3-2-1 chỉ là heuristic; threat model cần immutable/offline copy, account separation và restore credentials. Replica không thay backup vì delete/ransomware/operator error được replicate. Backup thành công chỉ chứng minh write path, không chứng minh restore path.'),
),('logical dump restore cần roles/extensions tồn tại hoặc được tái tạo','pg_dump một database không bao gồm toàn bộ cluster globals','parallel dump/restore đổi throughput nhưng vẫn cần đo restore critical path','filesystem copy khi database đang chạy có thể không nhất quán nếu không dùng supported snapshot protocol','physical backup gắn chặt hơn với major version và architecture','PITR cần base backup cộng chuỗi WAL không đứt','restore target time có rủi ro timezone/clock và transaction boundary','WAL retention ngắn hơn khoảng full backup làm mất restore window','replica truyền nhầm DELETE nên không phải backup','backup encryption cần key recovery tách biệt','checksum đúng không chứng minh logical completeness','configuration/roles/extensions/tablespaces phải nằm trong inventory','RPO/RTO phải phân tầng theo nghiệp vụ thay vì một số toàn công ty','retention phải tương thích quyền xóa và legal hold','backup chưa restore và reconcile chưa chứng minh recoverability')),M10,4,'SQL and Database Internals',10,'Storage Engine and Database Operations'),
Spec(KnowledgeLesson(146,'Lesson_146-the-restore-drill','The restore drill','34-the-restore-drill.md','wiki.database.restore-drill','Một restore drill phải có kịch bản, đồng hồ, đối soát và bằng chứng nào để chứng minh RPO/RTO thay vì chỉ chứng minh lệnh restore chạy?',PG+('src.book.kleppmann-ddia.1e',),PGL+('SRC-KLEPPMANN-DDIA-1E',),(
('Drill là phép thử hệ thống','Restore drill kiểm backup artifact, quyền truy cập, compute/storage capacity, version, extensions, keys, runbook, routing và con người. Success không phải process exit 0; database phải start, pass integrity checks, chứa đúng accepted operations ở target và phục vụ workload tối thiểu. Drill phải chạy trên máy/cluster mới để lộ dependency ẩn.'),
('Định nghĩa hai đồng hồ','RTO clock bắt đầu từ event được hợp đồng chọn: incident declaration hoặc recovery start; phải ghi rõ. Các mốc gồm detect, decide, provision, fetch, restore, replay, validate và route. RPO đo bằng operation-ID ledger/commit timestamps so với recovered set, không chỉ nhìn target time. Nếu writes tiếp tục ở hệ khác, cần ghi scope và reconciliation.'),
('Sáu pha','Một: freeze incident facts và target. Hai: provision isolated destination đúng version/capacity. Ba: lấy base/dump, catalog, keys và WAL. Bốn: restore/replay tới target có log. Năm: validate structural, row-level, invariant và application smoke. Sáu: quyết định cutover hoặc fail drill, ghi gaps và cập nhật runbook. Mỗi pha có owner, evidence và stop condition.'),
('Target trước lệnh phá hoại','Khôi phục ngay trước DROP/DELETE cần xác định destructive transaction boundary. Timestamp log chỉ là clue; named restore point/LSN/transaction ID đáng tin hơn nếu có. Nếu restore quá sớm thì tăng data loss; quá muộn thì mang lỗi vào. Có thể restore nhiều candidate isolated instances để tìm điểm đúng thay vì thử trên production.'),
('Đối soát','So schema/catalog, extensions, row counts theo partition, business control totals, sampled hashes, sequence positions và operation ledger. Row count bằng nhau vẫn có thể sai values; hash toàn bảng có thể đắt. Chọn invariant gắn nghiệp vụ và record false-positive boundaries. ANALYZE/statistics và permissions cũng ảnh hưởng service readiness.'),
('Học từ failure','Thiếu extension, major-version mismatch, disk full, corrupted segment, key unavailable, slow network và undocumented tablespace là test cases. Không sửa runbook trong trí nhớ; ghi exact command, precondition, expected output, decision point và rollback. Owner approval sau drill không thay evidence. Drill failure là phát hiện của control, không phải lý do hạ pass criteria.'),
),('restore trên chính máy hỏng làm mất containment và evidence','RTO clock phải có điểm bắt đầu được định nghĩa trước','RPO cần operation ledger để phân biệt lost, duplicate và late operations','target timestamp có thể lệch timezone hoặc nằm giữa transaction','missing WAL segment làm PITR không thể tiếp tục qua gap','extension/binary thiếu có thể cho restore partial rồi fail','disk capacity phải gồm base, WAL replay, temp và indexes','schema count đúng không chứng minh business invariant đúng','sequence thấp hơn max key có thể gây lỗi sau cutover','ANALYZE và cache warm-up ảnh hưởng readiness','credentials và TLS certificate là phần của restore dependency','application smoke phải dùng read/write path có kiểm soát','runbook command cần version pin và expected output','failed drill phải tạo action owner/deadline','không cutover nếu fencing/routing/rollback chưa rõ')),M10,4,'SQL and Database Internals',10,'Storage Engine and Database Operations'),
Spec(KnowledgeLesson(147,'Lesson_147-operating-a-database-day-to-day','Operating a database day to day','35-operating-a-database-day-to-day.md','wiki.database.day-two-operations','Bộ vận hành hằng ngày tối thiểu phải theo dõi resource, workload, maintenance và change như thế nào để phát hiện rủi ro trước người dùng?',PG,PGL,(
('Điều hành theo service objective','Dashboard chỉ có ý nghĩa khi gắn với availability, latency, correctness, durability và capacity objectives. Tách symptom metrics như query latency/error khỏi cause metrics như lock waits, IO, connection saturation, bloat hoặc replica lag. Baseline theo giờ/ngày và workload class; một ngưỡng tròn không phản ánh mùa vụ.'),
('Kết nối','max_connections là giới hạn, không phải target. Mỗi backend tiêu tốn memory/state; connection storm có thể làm database thất bại trước khi chạm hard limit. Pool giới hạn concurrency và queue ở lớp ứng dụng nhưng pool nhân theo replicas/pods. Theo dõi active, idle, idle-in-transaction, wait event, acquisition latency và rejected connections.'),
('Truy vấn và lock','Thu slow-query log hoặc pg_stat_statements theo policy, giữ query ID và distribution thay vì chỉ average. P95/P99 theo class, calls, total time, rows, temp IO và plans hỗ trợ ưu tiên. Theo dõi long transactions, blocker chains và deadlocks. Log có thể chứa dữ liệu nhạy cảm nên access/retention/redaction là control bắt buộc.'),
('Vacuum, statistics và storage','Theo dõi dead tuples, oldest transaction/XID age, autovacuum progress, table/index growth, last analyze và plan regressions sau bulk load. Disk alert dùng growth rate, time-to-exhaustion và headroom cho maintenance/recovery, không chỉ percent used. WAL/archive/slot retention có thể đầy volume khác với data volume.'),
('Backup, replication và change','Kiểm latest successful backup chưa đủ; theo dõi age của last restorable recovery point và restore-drill result. Replication theo send/write/flush/replay lag. Minor/major upgrade khác blast radius; mọi change có compatibility, backup, rehearsal, rollback và post-change verification. Extension/driver/OS cũng nằm trong matrix.'),
('Alert engineering','Alert phải actionable: condition, duration, severity, owner, dashboard/runbook link và suppression rule. Dẫn threshold từ baseline/SLO/capacity model, thử bằng sự cố cô lập và đo detection lead time. Tránh alert theo một sample; dùng burn rate hoặc sustained window phù hợp. Review false positive, missed incident và stale alert định kỳ.'),
),('pool size phải tính tổng qua mọi application instance','idle-in-transaction có thể giữ snapshot/lock dù active query bằng không','slow-query average che tail latency và bimodal plans','pg_stat_statements reset/restart làm đổi observation window','log statements có thể lộ secrets/PII và cần policy','dead tuples không đồng nhất bloat nhưng là input điều tra','oldest XID age là safety signal khác table size','bulk load làm statistics cũ và thay plan','disk percent thiếu growth rate và restore headroom','replication connected không đồng nghĩa replay current','replication slot có thể giữ WAL đến đầy disk','backup job green không thay restore drill','threshold cần baseline và service objective','alert không có owner/runbook không actionable','major upgrade cần rehearsal và rollback boundary')),M10,4,'SQL and Database Internals',10,'Storage Engine and Database Operations'),
Spec(KnowledgeLesson(148,'Lesson_148-gate-4-trace-a-write-and-defend-an-isolation-choice','Gate 4 - trace a write and defend an isolation choice','36-gate-4-write-trace-isolation-and-recovery.md','wiki.assessment.gate-4-database-internals','Gate 4 phải buộc người học tạo bằng chứng gì để chứng minh hiểu write path, SQL plans, isolation, locks, recovery và vận hành thay vì nhớ thuật ngữ?',PG+('src.book.petrov-database-internals.1e',),PGL+('SRC-PETROV-DATABASE-INTERNALS-1E',),(
('Gate đo năng lực tích hợp','Cổng không dạy khái niệm mới. Nó kiểm người học nối SQL statement, planner/executor, page/buffer, WAL, commit, checkpoint và recovery; đồng thời bảo vệ isolation theo anomaly và thực hiện restore. Điểm chỉ có ý nghĩa khi evidence artifact tái kiểm được. Phần bắt buộc có floor riêng để tổng điểm không che lỗ hổng an toàn.'),
('Phần A: trace write','Bài làm phải phân biệt logical statement, tuple/page mutation, dirty buffer, WAL record/LSN, WAL flush trước data page, commit acknowledgment, checkpoint và crash replay. Không yêu cầu engine internals giả tạo như mọi INSERT đều có cùng số WAL record. Diagram phải chỉ sync boundary và điều kiện durability theo cấu hình.'),
('Phần B: plan evidence','Hai query tuning bắt đầu bằng EXPLAIN ANALYZE BUFFERS có dữ liệu seed cố định, giữ result equivalence và so plan/counters trước sau. Không chấm chỉ bằng latency một lần. Candidate phải giải thích cardinality, access path, join, sort/spill và trade-off write/storage của index/rewrite.'),
('Phần C: isolation proof','Mỗi invariant có concurrent schedule với barriers, snapshots/reads, writes, commit/abort và final assertion. Chọn Read Committed, Repeatable Read, Serializable, explicit lock hoặc constraint dựa anomaly. Abort đúng thiết kế được chấp nhận nếu retry contract đầy đủ. Sequential test không chứng minh concurrency control.'),
('Phần D–F','Restore phần D cần target, operation ledger, RPO/RTO, reconciliation. Lock diagnosis phần E cần holder–waiter graph, resource và safe resolution. Operations phần F cần metrics, threshold derivation và lead time. Môi trường phải cô lập; phần recovery/kill/lock không chạy trên shared hoặc production database.'),
('Rubric và remediation','Rubric tách factual correctness, mechanism, evidence, reproducibility, safety và communication. C/D có floor vì isolation/recovery là năng lực không được bù bằng SQL. Vi phạm safety hoặc fabricate output là critical failure. Remediation nhắm đúng dimension: đọc lại, lab có scaffold, retest bằng dataset/schedule mới, không cho chép lại cùng đáp án.'),
),('write trace phải chỉ WAL-before-data rule và commit flush boundary','checkpoint không đồng nghĩa mọi dirty page đều durable ngay tại một điểm giản đơn','plan tuning phải chứng minh result equivalence','một latency sample không đủ đánh giá plan','index nhanh read nhưng tăng write/storage/maintenance','isolation phải chọn từ invariant và anomaly','sequential execution không tái hiện write skew','serialization abort có thể là kết quả đúng','retry phải chạy lại logical transaction từ snapshot mới','restore cần ledger và reconciliation','lock diagnosis phải dựng blocker chain','operations threshold phải có baseline','critical safety failure không được bù bằng tổng điểm','dataset retest phải khác practice case','artifact thiếu raw output không đạt reproducibility')),M10,4,'SQL and Database Internals',10,'Storage Engine and Database Operations'),
Spec(KnowledgeLesson(149,'Lesson_149-from-requirement-to-model-the-seven-step-protocol','From requirement to model - the seven-step protocol','37-from-requirement-to-model-seven-step-protocol.md','wiki.data-modeling.seven-step-protocol','Làm thế nào biến yêu cầu nghiệp vụ thành model bằng bảy bước mà không chọn schema pattern trước khi chốt process, grain, identity, time và workload?',('src.book.kimball-ross-data-warehouse-toolkit.3e','src.book.silberschatz-database-system-concepts.7e','src.book.kleppmann-ddia.1e'),('SRC-KIMBALL-ROSS-DW-TOOLKIT-3E','SRC-SILBERSCHATZ-DATABASE-SYSTEM-CONCEPTS-7E','SRC-KLEPPMANN-DDIA-1E'),(
('Nguồn gốc và phần mở rộng','Kimball–Ross đưa ra bốn bước theo thứ tự: chọn business process, khai báo grain, chọn dimensions và xác định facts. Giáo trình mở rộng thành bảy bước để dùng chung cho operational, analytical và domain models: process/event; grain; identity; measures/time; corrections/late/delete; workload/volume; rồi mới chọn modeling method. Bảy bước là synthesis của chương trình, không phải trích nguyên một framework có tên từ sách.'),
('Bước 1 — process và event','Gọi tên hoạt động tạo dữ liệu bằng động từ–đối tượng: nhận order, giao line item, ghi nhận payment, snapshot inventory. Không dùng tên phòng ban vì sales/marketing có thể dùng cùng orders process. Liệt kê event trigger, actor, source, business vocabulary và decision cần hỗ trợ. Chưa nói table/cột ở bước này.'),
('Bước 2 — grain','Viết một câu: mỗi row/record biểu diễn đúng một cái gì, tại thời điểm hoặc khoảng nào. Kiểm ba câu hỏi: một business event tạo bao nhiêu rows; hai rows phân biệt bằng gì; khi correction xảy ra row cũ bị thay, version hay có adjustment event. Grain là contract cho dimensions/facts; facts khác grain phải tách model.'),
('Bước 3–4 — identity, measures và time','Phân biệt natural/business identity với surrogate technical key, stability, reuse và cross-source matching. Với measure, ghi unit, aggregation/additivity, null/zero, currency và derivation. Time gồm event, effective, processing/ingestion và system/recorded time; không gọi chung một timestamp. Dimension/attribute phải có đúng một value tại grain hoặc dùng bridge/child design.'),
('Bước 5–6 — change và workload','Mô tả correction, cancellation, late-arriving fact/dimension, delete/retention và audit. Chọn overwrite, version, append adjustment hoặc bitemporal theo question cần trả lời. Sau đó ghi read/write shapes, joins, filters, freshness, volumes, growth, concurrency và retention. Model logic đúng nhưng không phục vụ access pattern vẫn chưa đủ.'),
('Bước 7 — chọn phương pháp','Chỉ sau sáu bước mới chọn normalized OLTP, dimensional star, Data Vault, document/event hoặc hybrid. Method là consequence của invariants, history và workload, không phải sở thích. Kimball process–grain–dimensions–facts là lựa chọn mạnh cho analytical presentation; operational domain cần transaction/invariant design khác. Quyết định ghi trade-off và rejected alternatives.'),
),('business process không đồng nhất organizational department','grain phải là câu mô tả một row chứ không phải cụm danh từ','facts phải đúng grain và khác grain cần table khác','dimension value phải đơn trị tại grain hoặc cần bridge','natural key có thể đổi/reuse và cần stability analysis','surrogate key không tự giải entity resolution','event time khác processing/effective/system time','late fact khác late dimension về lookup và correction','delete cần semantics nghiệp vụ, retention và audit','access patterns đến trước physical method selection','source schema không thay business interview','star schema không phải đáp án mặc định cho operational workload','lowest useful grain giữ drill-down nhưng tăng volume','reader paraphrase test phát hiện grain mơ hồ','mọi bước cần artifact và trace về requirement')),M11,5,'Modeling, Semantics and Analytical Product',11,'Data Modeling - Operational, Analytical and Domain'),
)

def folder(s): return ROOT/s.base/s.k.directory
def field(t,n):
 m=re.search(rf'(?m)^\*\*{re.escape(n)}\.\*\*\s*(.+)$',t)
 if not m: raise ValueError(f'missing {n}')
 return m.group(1).strip()
def section(t,h):
 m=re.search(rf'(?ms)^## {re.escape(h)}\n\n(.*?)(?=^## |\Z)',t)
 if not m: raise ValueError(f'missing {h}')
 return m.group(1).strip()
def contract(s):
 n=(folder(s)/'note.md').read_text(); a=(folder(s)/'after-note.md').read_text()
 if '**Outcome.**' in n: return tuple(field(n,k) for k in ('Outcome','Đánh giá','Lab','Pitfalls','Self-study (2,4 giờ)','Done when'))
 return (field(section(n,'Mục tiêu bài học'),'Năng lực cần chứng minh'),field(section(a,'Tiêu chí hoàn thành'),'Cách đánh giá'),field(section(a,'Thực hành'),'Nhiệm vụ'),field(section(a,'Bài làm sau buổi học'),'Lỗi cần chủ động loại trừ'),field(section(a,'Bài làm sau buổi học'),'Nhiệm vụ'),field(section(n,'Mục tiêu bài học'),'Điều kiện hoàn thành'))
def curriculum(s,k):
 outcome,assessment,lab,pitfalls,homework,done=contract(s)
 h=f'# Phase {s.phase}: {s.phase_title}\n# Module {s.module}: {s.module_title}\n# Lesson {s.k.number}: {s.k.title}'
 body=re.sub(r'^---\n.*?\n---\n','',k,flags=re.S); body=re.sub(r'^# .+\n+','',body,count=1)
 n=f'{h}\n\n## Mục tiêu bài học\n\n**Năng lực cần chứng minh.** {outcome}\n\n**Điều kiện hoàn thành.** {done}\n\n{body}'
 safety='Chỉ chạy backup/restore, fault injection, lock workload hoặc schema experiment trong môi trường cô lập có dữ liệu giả và đường xoá/khôi phục rõ. Không restore đè, đổi retention, kill process hoặc chạy destructive command trên production. Lưu exact version, config, script, raw log, operation ledger và kết quả đối soát.'
